import json,hashlib
from pathlib import Path
root=Path.home()/'dojo-data/laptop';out={'diagnostics':{},'pilots':[],'recipes':{},'admissions':{},'screens':[],'rows':[],'manifests':{}}
for p in (root/'round2g').glob('*.json'):out['diagnostics'][p.name]=json.loads(p.read_text())
for p in (root/'round2g').glob('*/row.json'):out['pilots'].append({'path':str(p.relative_to(root)),'row':json.loads(p.read_text())})
for p in list(root.glob('round2g*.py')):
 out['recipes'][p.name]={'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'source':p.read_text()}
for p in (root/'logs').glob('r2g-*.admission'):out['admissions'][p.name]=p.read_text()
for bank,data in [('old',root),('coverage18',root/'coverage18')]:
 for d in data.glob('r2g-production-*'):
  if not d.is_dir():continue
  for p in d.glob('*_episodes.jsonl'):
   out['screens'].extend({'bank':bank,'run_dir':str(d.relative_to(root)),'row':json.loads(l)} for l in p.read_text().splitlines())
for d in root.glob('r2g-panel-*'):
 if not d.is_dir():continue
 for p in d.glob('*_episodes.jsonl'):
  out['rows'].extend(dict(json.loads(l),run_dir=d.name) for l in p.read_text().splitlines())
for p in root.glob('round2g-*.json'):
 if 'expected' not in p.name:out['manifests'][p.name]=json.loads(p.read_text())
for p in [root/'job-g.sh',root/'job-panel-g.sh']:
 if p.exists():out['recipes'][p.name]={'source':p.read_text()}
print(json.dumps(out))

