import json
from pathlib import Path
from dojo.simlab import paths
from dojo.simlab.gen_layouts import generate
root=paths.DATA;gate={}
expected_flags=dict(hang_cradle='straddle',hang_wide='on',headset_seat='on',headset_carry='staged',headset_grasp='cups',headset_table='mesh',headset_stage='mesh_clear',headset_retry='sites',headset_lift='slow',headset_hold='loaded')
for task,name in [('store_laptop_and_headphones','std'),('store_laptop_and_headphones_random','random')]:
 assert (root/f'round2g-production-done-{name}').exists(),f'screen unfinished: {name}'
 gate[task]={}
 for bank,data,expected,minimum in [('old',root,{100030,100031,*range(100045,100050),*range(100065,100070)},9),('coverage18',root/'coverage18',set(range(100030,100040)),8)]:
  rows=[]
  for p in data.glob(f'r2g-production-{name}-{bank}-*/*_episodes.jsonl'):
   rows += [json.loads(l) for l in p.read_text().splitlines()]
  assert len(rows)==len(expected) and {r['seed'] for r in rows}==expected,(task,bank,len(rows))
  assert all(r['code']['commit']=='04132591' and r['skill_attrs']==expected_flags and r['stable'] and not r.get('missing_meshes') for r in rows)
  credits=sum(any(abs(float(r['score'])-v)<1e-6 for v in (.2,1.)) for r in rows)
  assert credits>=minimum,(task,bank,credits,minimum)
  gate[task][bank]={'n':len(rows),'headset_credits':credits,'minimum':minimum}
for task in gate:
 for i in range(100000,100015):
  for suffix in ('','.settled'):
   p=paths.LAYOUTS/task/f'{i}{suffix}.json'
   assert not p.exists(),f'refuse existing record {p}'
(root/'round2g-screen-gate.json').write_text(json.dumps(gate,indent=2))
for task in gate:
 for i in range(100000,100015):
  p=paths.LAYOUTS/task/f'{i}.json'
  lay=generate(task,i,variant=20,seed_salt='laptop-round2g-loaded-2026-11-07-88c48b74')
  with p.open('x') as f:json.dump(lay,f,indent=1)
  print(task,i,flush=True)
